describe('Order Summary', () => {
    beforeEach(() => {
        cy.visit('/checkout');
        cy.get('#add-to-cart-button').click();
        cy.get('#proceed-to-checkout-button').click();
    });

    it('should display the order summary before confirming payment (happy path)', () => {
        cy.get('#order-summary').should('be.visible');
        cy.get('#order-summary .item-name').should('contain', 'Product Name');
        cy.get('#order-summary .item-price').should('contain', '$99.99');
        cy.get('#total-amount').should('contain', '$99.99');
        cy.get('#confirm-payment-button').should('be.enabled');
    });

    it('should not display the order summary if no items are in the cart (edge case)', () => {
        cy.visit('/checkout');
        cy.get('#order-summary').should('not.exist');
        cy.get('#confirm-payment-button').should('be.disabled');
    });
});
